sys_script_include.script:
var DataSilos = Class.create();
DataSilos.prototype = {
    initialize: function() {
    },

    GetConfig: function(config)
	{
		var IsFunction = x_snc_devtools.IsFunction;
		if (IsActive() && IsFunction(x_snc_datasilos_ci.DataSilosGetConfig))
		{
			config = DataSilosGetConfig(config);
		}
        return config;
    },

    GetRelatedRecords: function(record)
	{
		var IsFunction = x_snc_devtools.IsFunction;
		if (IsActive() && IsFunction(x_snc_datasilos_ci.DataSilosGetRelatedRecords))
		{
			return DataSilosGetRelatedRecords(record);
		}
        return false;
    },		

    RecordInsert: function(record)
	{
		var IsFunction = x_snc_devtools.IsFunction;
		if (IsActive() && IsFunction(x_snc_datasilos_ci.DataSilosRecordInsert))
		{
			return DataSilosRecordInsert(record);
		}
        return false;
    },		

    RecordUpdate: function(record)
	{
		var IsFunction = x_snc_devtools.IsFunction;
		if (IsActive() && IsFunction(x_snc_datasilos_ci.DataSilosRecordUpdate))
		{
			return DataSilosRecordUpdate(record);
		}
        return false;
    },	

    GetStatus: function(status)
	{
		var IsFunction = x_snc_devtools.IsFunction;
		if (IsActive() && IsFunction(x_snc_datasilos_ci.DataSilosGetStatus))
		{
			status = DataSilosGetStatus(status);
		}
        return status;
    },	

	PrepareQuery: function(record,
		strTable,
		strPrefix,
		strUserSysId,
		bAllowEmptySysId,
		aUserSupervisorSilos,
		aUserFulfillerSilos,
		aUserGroups,
		nUserSecurityClearance)
	{
		var IsFunction = x_snc_devtools.IsFunction;
		if (IsActive() && IsFunction(x_snc_datasilos_ci.DataSilosPrepareQuery))
		{
			return DataSilosPrepareQuery(record,
				strTable,
				strPrefix,
				strUserSysId,
				bAllowEmptySysId,
				aUserSupervisorSilos,
				aUserFulfillerSilos,
				aUserGroups,
				nUserSecurityClearance);
		}
        return false;
    },		

    AccessAnalysis: function(result)
	{
		var IsFunction = x_snc_devtools.IsFunction;
		if (IsActive() && IsFunction(x_snc_datasilos_ci.DataSilosAccessAnalysis))
		{
			result = DataSilosAccessAnalysis(result);
		}
        return result;
    },		

    type: 'DataSilos'
};
